CREATE OR REPLACE FUNCTION public.dmf_check_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare current_count integer;deadline timestamptz;
begin
if length(p_key)<>64 or p_limit not between 1 and 1000 or p_window_seconds not between 1 and 86400 then raise exception 'Invalid limit' using errcode='22023';end if;
delete from public.intake_rate_limits where expires_at<now()-interval '1 day';
insert into public.intake_rate_limits as limits(key,count,expires_at) values(p_key,1,now()+make_interval(secs=>p_window_seconds)) on conflict(key) do update set count=case when limits.expires_at<=now() then 1 else least(limits.count+1,p_limit+1) end,expires_at=case when limits.expires_at<=now() then now()+make_interval(secs=>p_window_seconds) else limits.expires_at end returning count,expires_at into current_count,deadline;
return jsonb_build_object('success',current_count<=p_limit,'remaining',greatest(p_limit-current_count,0),'resetIn',greatest(1,ceil(extract(epoch from deadline-now()))::integer));
end $function$

CREATE OR REPLACE FUNCTION public.dmf_claim_notification(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare job public.notification_deliveries;submission public.intake_submissions;
begin
update public.notification_deliveries set status='sending',attempts=attempts+1,attempt_token=gen_random_uuid(),lease_until=now()+interval '5 minutes',updated_at=now() where id=p_id and (status in ('pending','failed','skipped') or (status='sending' and lease_until<now())) returning * into job;
if job.id is null then return null;end if;
select * into submission from public.intake_submissions where id=job.submission_id;
return jsonb_build_object('id',job.id,'attemptToken',job.attempt_token,'channel',job.channel,'kind',submission.kind,'payload',submission.payload);
end $function$

CREATE OR REPLACE FUNCTION public.dmf_preserve_post_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform pg_advisory_xact_lock(192837465);
 if TG_OP='UPDATE' and new.slug=old.slug then return new; end if;
 if new.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(new.slug)>200 then raise exception 'Invalid blog slug' using errcode='23514'; end if;
 if exists(select 1 from public.post_slug_redirects where slug=new.slug and post_id<>new.id) then raise exception 'This slug belongs to a previous publication' using errcode='23505'; end if;
 delete from public.post_slug_redirects where slug=new.slug and post_id=new.id;
 if TG_OP='UPDATE' and (old.status='published' or old.published_at is not null) then insert into public.post_slug_redirects(slug,post_id) values(old.slug,old.id) on conflict(slug) do nothing; end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.dmf_receive_intake(p_id uuid, p_kind text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare digest text; existing_hash text; existing_kind text; saved_id uuid; profile_id uuid;
begin
 if p_id is null or p_kind not in ('contact','profile','lead') or jsonb_typeof(p_payload) is distinct from 'object'
 or octet_length(p_payload::text)>30000 or nullif(btrim(p_payload->>'email'),'') is null
 or length(p_payload->>'email')>320 then raise exception 'Invalid intake' using errcode='22023'; end if;
 digest:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
 insert into public.intake_submissions(id,kind,payload,payload_hash) values(p_id,p_kind,p_payload,digest)
 on conflict(id) do nothing;
 if not found then
 select payload_hash,kind into existing_hash,existing_kind from public.intake_submissions where id=p_id;
 if existing_hash is distinct from digest or existing_kind is distinct from p_kind then
 raise exception 'Idempotency conflict' using errcode='23505';
 end if;
 return jsonb_build_object('duplicate',true);
 end if;
 if p_kind='lead' then
 insert into public.leads(email,company,phone,interest,session_id,source,status,source_path,campaign)
 values(p_payload->>'email',nullif(p_payload->>'company',''),nullif(p_payload->>'phone',''),
 p_payload->>'interest',p_payload->>'sessionId','chatbot','new',p_payload->>'sourcePath',coalesce(p_payload->'campaign','{}'::jsonb))
 returning id into saved_id;
 else
 if p_kind='profile' then
 profile_id := (p_payload->>'candidateId')::uuid;
 if not exists(select 1 from public.candidates where id=profile_id and publication_status = 'published' and publication_valid_until >= current_date) then
 raise exception 'Profile unavailable' using errcode='P0002';
 end if;
 end if;
 insert into public.inquiries(client_name,email,phone,company,message,type,status,candidate_id,candidate_code,request_purpose,service,headcount,work_location,start_window,source_path,campaign)
 values(p_payload->>'name',p_payload->>'email',nullif(p_payload->>'phone',''),nullif(p_payload->>'company',''),
 p_payload->>'message',p_kind,'new',profile_id,case when profile_id is null then null else upper(left(profile_id::text,8)) end,
 p_payload->>'requestPurpose',p_payload->>'service',(p_payload->>'headcount')::integer,p_payload->>'location',p_payload->>'timing',p_payload->>'sourcePath',coalesce(p_payload->'campaign','{}'::jsonb))
 returning id into saved_id;
 end if;
 update public.intake_submissions set record_id=saved_id where id=p_id;
 insert into public.notification_deliveries(submission_id,channel) values(p_id,'email'),(p_id,'telegram');
 if p_kind<>'lead' then insert into public.notification_deliveries(submission_id,channel) values(p_id,'auto_reply'); end if;
 return jsonb_build_object('duplicate',false);
end $function$

CREATE OR REPLACE FUNCTION public.dmf_request_workflow_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.assigned_to is not null and (TG_OP='INSERT' or new.assigned_to is distinct from old.assigned_to) then
 if not exists(select 1 from public.dmf_request_assignees() a where a.id=new.assigned_to) then
 raise exception 'Owner must be an existing administrator' using errcode='23514';
 end if;
 end if;
 if TG_OP='UPDATE' then
 new.workflow_version := old.workflow_version+1;
 new.updated_at := clock_timestamp();
 if new.notes is distinct from old.notes and length(new.notes)>10000 then
 raise exception 'Notes too long' using errcode='23514';
 end if;
 else new.workflow_version := 0;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.dmf_review_candidate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 new.updated_at := clock_timestamp();
 if TG_OP = 'INSERT' and new.publication_status <> 'draft' then raise exception 'Save a draft before reviewing publication' using errcode='23514'; end if;
 if TG_OP = 'UPDATE' then
  if row(new.category,new.profession,new.experience_years,new.german_level,new.visa_status,new.avatar_url,new.video_url) is distinct from row(old.category,old.profession,old.experience_years,old.german_level,old.visa_status,old.avatar_url,old.video_url) then new.publication_status := 'draft'; end if;
  if new.publication_status = 'published' and (old.publication_status <> 'published' or row(new.publication_valid_until,new.publication_consent_note) is distinct from row(old.publication_valid_until,old.publication_consent_note)) then
   if not public.dmf_is_admin() then raise exception 'Admin review required' using errcode='42501'; end if;
   if new.publication_valid_until < current_date then raise exception 'Publication validity must not be in the past' using errcode='23514'; end if;
   if new.full_name ~* '(^|[^a-z])(test|demo|sample|muster)([^a-z]|$)' or new.profession ~* '(^|[^a-z])(test|demo|sample|muster)([^a-z]|$)' or coalesce(new.video_url,'') like '%dQw4w9WgXcQ%' then raise exception 'Sample content cannot be published' using errcode='23514'; end if;
   new.publication_reviewed_at := now(); new.publication_reviewed_by := auth.uid();
  else new.publication_reviewed_at := old.publication_reviewed_at; new.publication_reviewed_by := old.publication_reviewed_by;
  end if;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.dmf_validate_profile_inquiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.candidate_id is not null and not exists (select 1 from public.candidates where id=new.candidate_id and publication_status='published' and publication_valid_until >= current_date) then raise exception 'Profile unavailable' using errcode='P0002'; end if;
 return new;
end;
$function$
